    "focusTarget": "#ppoSvg"
  },
  {
    "id": "64_kl_demo1_explain_contribution",
    "narration": "The yellow bar for 'the' in the KL contribution chart shows that most of the divergence comes from this token. KL divergence pinpoints exactly where the policy has shifted.",
    "focusTarget": "#klContribSvg"
  }
